    Priority is ``first`` then ``limit`` (the complexity-only bounds),
    then the stable-paging ``pageSize`` argument; any absent, non-positive
    or non-integer candidate is skipped in favor of the next one, and
    without a usable bound the field uses DEFAULT_LIST_BOUND.
    """
    for arg_name in BOUND_ARG_NAMES + (PAGING_SIZE_ARG,):
        if arg_name in node.args:
            bound = self._resolve_bound(node.args[arg_name])
            if bound is not None:
                return bound
    return DEFAULT_LIST_BOUND

